import { InspirationDialog } from "@/features/inspiration/inspiration-dialog";
import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useState } from "react";

export const Route = createFileRoute("/orgs/$orgSlug/inspirations/new")({
  component: NewInspirationRoute,
});

function NewInspirationRoute() {
  const { orgSlug } = Route.useParams();
  const navigate = useNavigate({ from: "/orgs/$orgSlug/inspirations/new" });
  const [open, setOpen] = useState(true);

  const closeToList = () => {
    setOpen(false);
    void navigate({ to: `/orgs/${orgSlug}/inspirations` });
  };

  return (
    <InspirationDialog
      open={open}
      onOpenChange={(nextOpen) => {
        if (!nextOpen) closeToList();
        setOpen(nextOpen);
      }}
      onSuccess={(inspirationId) => {
        void navigate({
          to: `/orgs/${orgSlug}/inspirations/${inspirationId}`,
        });
      }}
    />
  );
}

import { TitleUpdateForm } from "@/components/nowts/title-update-form";
import { Badge } from "@/components/ui/badge";
import { Button, buttonVariants } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  InspirationDetailDialog,
  InspirationSourceVideoCard,
} from "@/features/inspiration/inspiration-detail-dialog";
import type { InspirationListItem } from "@/features/inspiration/inspiration.query";
import { useInspiration } from "@/features/inspiration/inspiration.query";
import {
  Layout,
  LayoutActions,
  LayoutContent,
  LayoutHeader,
} from "@/features/page/layout";
import { useCurrentOrg } from "@/features/organization/current-org-store";
import { LoadingState } from "@/features/organization/loading-state";
import Image from "@/compat/image";
import Link from "@/compat/link";
import { formatDate } from "@/lib/format/date";
import { formatScopedTitle } from "@/lib/metadata";
import { usePageMetadata } from "@/lib/use-page-metadata";
import { createFileRoute } from "@tanstack/react-router";
import { useMutation as useConvexMutation } from "convex/react";
import { makeFunctionReference } from "convex/server";
import {
  Calendar,
  ExternalLink,
  ImageIcon,
  Pencil,
  User,
  UserX,
} from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

const updateInspirationNameRef = makeFunctionReference<
  "mutation",
  { orgSlug: string; inspirationId: string; name: string },
  { id: string; name: string }
>("inspiration:updateName");

export const Route = createFileRoute(
  "/orgs/$orgSlug/inspirations/$inspirationId",
)({
  component: InspirationDetailRoute,
});

function InspirationDetailRoute() {
  const { orgSlug, inspirationId } = Route.useParams();
  const currentOrg = useCurrentOrg();
  const { data: inspiration, isLoading } = useInspiration(
    orgSlug,
    inspirationId,
  );
  const updateInspirationName = useConvexMutation(updateInspirationNameRef);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [localInspiration, setLocalInspiration] =
    useState<InspirationListItem | null>(null);
  const activeInspiration =
    localInspiration?.id === inspirationId ? localInspiration : inspiration;
  const firstThumbnail = activeInspiration?.thumbnailUrls[0];

  usePageMetadata(
    activeInspiration
      ? {
          title: formatScopedTitle([
            activeInspiration.name,
            currentOrg?.name ?? orgSlug,
          ]),
          description: activeInspiration.aiDescription,
          image: firstThumbnail,
          path: `/orgs/${orgSlug}/inspirations/${inspirationId}`,
          noIndex: true,
        }
      : null,
  );

  if (isLoading || !activeInspiration) {
    return <LoadingState label="Loading inspiration" />;
  }

  const saveTitle = async (name: string) => {
    try {
      await updateInspirationName({ orgSlug, inspirationId, name });
      setLocalInspiration({ ...activeInspiration, name });
      toast.success("Inspiration renamed");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Failed to rename");
    }
  };

  return (
    <Layout size="lg">
      <LayoutHeader>
        <TitleUpdateForm
          key={`${orgSlug}:${inspirationId}:${activeInspiration.name}`}
          title={activeInspiration.name}
          onUpdate={saveTitle}
        />
      </LayoutHeader>
      <LayoutActions>
        <Link
          href={`/orgs/${orgSlug}/thumbnails/new?inspiration=${activeInspiration.id}`}
          className={buttonVariants()}
        >
          Use this inspiration
        </Link>
        <Button variant="outline" onClick={() => setDialogOpen(true)}>
          <Pencil className="mr-2 size-4" />
          Edit Reference
        </Button>
      </LayoutActions>

      <LayoutContent className="flex flex-col gap-6">
        <div className="flex flex-wrap items-center gap-2 border-b pb-4">
          {activeInspiration.category ? (
            <Badge variant="secondary">{activeInspiration.category}</Badge>
          ) : null}
          <Badge variant="outline" className="gap-1">
            <Calendar size={12} />
            {formatDate(new Date(activeInspiration.createdAt))}
          </Badge>
          <Badge
            variant={activeInspiration.hasPlaceholder ? "secondary" : "outline"}
            className="gap-1"
          >
            {activeInspiration.hasPlaceholder ? (
              <UserX size={12} />
            ) : (
              <User size={12} />
            )}
            {activeInspiration.hasPlaceholder ? "Anonymized" : "Original"}
          </Badge>
          {activeInspiration.youtubeUrl ? (
            <Link
              href={activeInspiration.youtubeUrl}
              target="_blank"
              rel="noopener noreferrer"
            >
              <Badge variant="outline" className="gap-1" asChild>
                <span>
                  <ExternalLink size={12} />
                  YouTube Source
                </span>
              </Badge>
            </Link>
          ) : null}
        </div>

        {firstThumbnail ? (
          <div className="relative aspect-video w-full overflow-hidden rounded-lg border">
            <Image
              src={firstThumbnail}
              alt={activeInspiration.name}
              fill
              className="object-cover"
              priority
            />
          </div>
        ) : (
          <div className="bg-muted flex aspect-video w-full items-center justify-center rounded-lg border">
            <ImageIcon className="text-muted-foreground size-12" />
          </div>
        )}

        <InspirationSourceVideoCard inspiration={activeInspiration} />

        {activeInspiration.aiDescription ? (
          <header className="flex flex-col gap-2 border-b pb-6">
            <h2 className="text-sm font-medium">AI Description</h2>
            <p className="text-muted-foreground whitespace-pre-wrap">
              {activeInspiration.aiDescription}
            </p>
          </header>
        ) : null}

        {activeInspiration.thumbnailUrls.length > 1 ? (
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4">
            {activeInspiration.thumbnailUrls.slice(1).map((url, index) => (
              <div
                key={`${url}-${index}`}
                className="bg-muted relative aspect-video overflow-hidden rounded-lg border"
              >
                <Image
                  src={url}
                  alt={`Thumbnail ${index + 2}`}
                  fill
                  className="object-cover"
                />
              </div>
            ))}
          </div>
        ) : null}

        <Card>
          <CardHeader>
            <CardTitle>Your Thumbnails</CardTitle>
            <CardDescription>
              Thumbnails you created using this inspiration
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex flex-col items-center justify-center py-8 text-center">
              <p className="text-muted-foreground text-sm">
                Create a thumbnail with this inspiration to see it here.
              </p>
              <Link
                href={`/orgs/${orgSlug}/thumbnails/new?inspiration=${activeInspiration.id}`}
                className={buttonVariants({
                  variant: "secondary",
                  size: "sm",
                  className: "mt-4",
                })}
              >
                Create your first
              </Link>
            </div>
          </CardContent>
        </Card>
      </LayoutContent>

      <InspirationDetailDialog
        inspiration={activeInspiration}
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        currentOrgId={currentOrg?.id ?? ""}
        orgSlug={orgSlug}
        onImagesUpdated={(thumbnailUrls) => {
          setLocalInspiration({ ...activeInspiration, thumbnailUrls });
        }}
        onInspirationCopied={(newInspiration) => {
          setLocalInspiration(newInspiration);
        }}
        onInspirationAnonymized={(updatedInspiration) => {
          setLocalInspiration(updatedInspiration);
        }}
      />
    </Layout>
  );
}

import { z } from "zod";
import { isValidYoutubeUrl } from "./youtube-utils";

export const InspirationYoutubeSchema = z.object({
  type: z.literal("youtube"),
  youtubeUrl: z
    .string()
    .min(1, "YouTube URL is required")
    .refine(isValidYoutubeUrl, "Invalid YouTube URL"),
  anonymize: z.boolean().optional(),
  anonymizeSubject: z.boolean().optional(),
  anonymizeText: z.boolean().optional(),
  anonymizeLogos: z.boolean().optional(),
});

export const InspirationUploadSchema = z.object({
  type: z.literal("upload"),
  imageUrls: z.array(z.string()).min(1, "At least one image is required"),
  anonymize: z.boolean().optional(),
  anonymizeSubject: z.boolean().optional(),
  anonymizeText: z.boolean().optional(),
  anonymizeLogos: z.boolean().optional(),
});

export const CreateInspirationSchema = z.discriminatedUnion("type", [
  InspirationYoutubeSchema,
  InspirationUploadSchema,
]);

export type CreateInspirationInput = z.infer<typeof CreateInspirationSchema>;

export const UpdateInspirationSchema = z.object({
  inspirationId: z.string(),
  aiDescription: z.string().min(1, "Description is required"),
});

export type UpdateInspirationInput = z.infer<typeof UpdateInspirationSchema>;

export const UpdateInspirationImagesSchema = z.object({
  inspirationId: z.string(),
  thumbnailUrls: z.array(z.string()).min(1, "At least one image is required"),
  isPublic: z.boolean(),
});

export type UpdateInspirationImagesInput = z.infer<
  typeof UpdateInspirationImagesSchema
>;

export const AnonymizeInspirationSchema = z.object({
  inspirationId: z.string(),
  mode: z.enum(["replace", "duplicate"]),
});

export const UpdateInspirationNameSchema = z.object({
  inspirationId: z.string(),
  name: z.string().min(1, "Name is required"),
});

import type { ThumbnailCategory } from "@/lib/ai/gemini";
import { useConvexInfiniteQuery } from "@/hooks/use-convex-infinite-query";
import { useQuery as useConvexQuery } from "convex/react";
import { makeFunctionReference } from "convex/server";

export type InspirationFilter = "mine" | "all";
export type AdminReviewStatus = "GOOD" | "APPROVED" | "PENDING" | "DENY";

export type InspirationListItem = {
  id: string;
  name: string;
  aiDescription: string;
  category: ThumbnailCategory | null;
  thumbnailUrls: string[];
  createdAt: string;
  adminReview: AdminReviewStatus;
  isPublic: boolean;
  orgId: string;
  hasPlaceholder: boolean;
  anonymizedSubject: boolean;
  anonymizedText: boolean;
  anonymizedLogos: boolean;
  anonymizedTextDescription: string | null;
  youtubeUrl: string | null;
  sourceVideoTitle: string | null;
  sourceVideoAuthor: string | null;
  sourceVideoThumbnailUrl: string | null;
};

export type Inspiration = InspirationListItem;

export function isAnonymizedInspiration(
  inspiration: Pick<
    InspirationListItem,
    "hasPlaceholder" | "thumbnailUrls" | "anonymizedSubject"
  >,
) {
  return inspiration.anonymizedSubject || inspiration.hasPlaceholder;
}

type InfiniteInspirationsResponse = {
  items: InspirationListItem[];
  nextCursor: string | undefined;
};

const INSPIRATIONS_PAGE_SIZE = 60;

export const listInspirationsRef = makeFunctionReference<
  "query",
  {
    orgSlug: string;
    filter?: InspirationFilter;
    search?: string;
    category?: ThumbnailCategory;
    cursor?: string;
    limit?: number;
  },
  InfiniteInspirationsResponse
>("inspiration:list");

export const inspirationDetailRef = makeFunctionReference<
  "query",
  { orgSlug: string; inspirationId: string },
  Inspiration
>("inspiration:detail");

export const searchInspirationsRef = makeFunctionReference<
  "query",
  { orgSlug: string; q?: string; limit?: number },
  InspirationListItem[]
>("inspiration:search");

export const inspirationKeys = {
  all: ["inspirations"] as const,
  list: (orgSlug: string, filter: InspirationFilter) =>
    [...inspirationKeys.all, "list", orgSlug, filter] as const,
  infinite: (
    orgSlug: string,
    filter: InspirationFilter,
    search?: string,
    category?: ThumbnailCategory,
  ) =>
    [
      ...inspirationKeys.all,
      "infinite",
      orgSlug,
      filter,
      search,
      category,
    ] as const,
  detail: (orgSlug: string, inspirationId: string) =>
    [...inspirationKeys.all, "detail", orgSlug, inspirationId] as const,
};

export function useInspirations(
  orgSlug: string,
  filter: InspirationFilter = "mine",
) {
  const data = useConvexQuery(
    listInspirationsRef,
    orgSlug ? { orgSlug, filter } : "skip",
  );
  return { data, isLoading: data === undefined };
}

export function useInspiration(orgSlug: string, inspirationId: string) {
  const data = useConvexQuery(
    inspirationDetailRef,
    orgSlug && inspirationId ? { orgSlug, inspirationId } : "skip",
  );
  return { data, isLoading: data === undefined };
}

export function useInfiniteInspirations(
  orgSlug: string,
  filter: InspirationFilter = "mine",
  search?: string,
  category?: ThumbnailCategory,
) {
  return useConvexInfiniteQuery<InspirationListItem>(
    listInspirationsRef,
    orgSlug
      ? {
          orgSlug,
          filter,
          search,
          category,
        }
      : null,
    {
      keyParts: [orgSlug, filter, search ?? "", category ?? ""],
      pageSize: INSPIRATIONS_PAGE_SIZE,
    },
  );
}

