type AppCtx = {
  db: any;
  runQuery: (fn: any, args: any) => Promise<any>;
  runMutation?: (fn: any, args: any) => Promise<any>;
};

type StoredImage = {
  url: string;
  key?: string;
  width?: number;
  height?: number;
  contentType?: string;
};

type InspirationRow = {
  _id: string;
  organizationId: string;
  title: string;
  description?: string;
  sourceUrl?: string;
  sourceVideoTitle?: string;
  sourceVideoAuthor?: string;
  sourceVideoThumbnailUrl?: string;
  drawingData?: string;
  image?: StoredImage;
  images?: StoredImage[];
  categories?: string[];
  hasPlaceholder?: boolean;
  anonymizedSubject?: boolean;
