        )}
      </SidebarHeader>
      <SidebarContent className="border-card">
        {props.navigationGroups.map((group) => (
          <SidebarGroup key={group.title}>
            <SidebarGroupLabel>{group.title}</SidebarGroupLabel>
            <SidebarGroupContent>
              <SidebarMenu>
                {group.links.map((item) => {
                  return (
                    <SidebarMenuItem key={item.href}>
                      <SidebarMenuButton
                        asChild
                        isActive={bestMatch === item.href}
                      >
                        <Link to={item.href as never}>
                          <item.Icon />
                          <span>{item.label}</span>
                          {item.badge ? (
                            <span className="bg-primary/10 text-primary ml-auto rounded px-1.5 py-0.5 text-[10px] leading-none font-medium">
                              {item.badge}
                            </span>
                          ) : null}
                        </Link>
                      </SidebarMenuButton>
                    </SidebarMenuItem>
                  );
                })}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        ))}
      </SidebarContent>
      <SidebarFooter className="flex flex-col gap-2">
        {!props.isSettingsPage ? (
          <>
            <div className="flex items-center gap-3 px-2">
              <a
                className="text-muted-foreground text-xs hover:underline"
                href="/docs"
              >
                Docs
              </a>
              <a
                className="text-muted-foreground text-xs hover:underline"
                href="/changelog"
              >
                Changelog
              </a>
            </div>
            <Button variant="outline" asChild size="sm">
              <Link to={`/orgs/${props.orgSlug}/settings` as never}>
                <Settings className="size-4" />
                <span>Settings</span>
              </Link>
            </Button>
          </>
        ) : (
          <div className="flex items-center gap-3 px-2">
            <a
              className="text-muted-foreground text-xs hover:underline"
              href="/docs"
            >
              Docs
            </a>
            <a
              className="text-muted-foreground text-xs hover:underline"
              href="/legal/terms"
