import {
  createInspirationRef,
  uploadInspirationImageRef,
} from "./inspiration.convex";
import {
  BorderedDialogBody,
  BorderedDialogContent,
  BorderedDialogFooter,
  BorderedDialogHeader,
  DialogEscClose,
} from "@/components/bordered-dialog";
