              title="Inspirations tutorial"
              className="size-full"
              allowFullScreen
              allow="autoplay; fullscreen"
            />
          </div>
          <Link
            href="/docs/guides/inspiration-guide"
            className={buttonVariants({ variant: "outline" })}
          >
            <BookOpen className="mr-2 size-4" />
            Read Full Documentation
          </Link>
        </div>
      ),
    });
  };

  const updateFilter = (nextFilter: InspirationFilter) => {
    void navigate({
      search: (previous) => ({ ...previous, filter: nextFilter }),
    });
  };

  return (
    <Layout size="lg">
      <LayoutHeader>
        <LayoutTitle>Inspirations</LayoutTitle>
      </LayoutHeader>
      <LayoutActions>
        <Button
          variant="outline"
          className="hidden md:inline-flex"
          onClick={openTutorialDialog}
        >
          <PlayCircle className="mr-2 size-4" />
          Watch Tutorial
        </Button>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="icon" className="md:hidden">
              <EllipsisVertical className="size-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={openTutorialDialog}>
              <PlayCircle className="mr-2 size-4" />
              Watch Tutorial
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button>
              <Plus className="mr-2 size-4" />
              Add Inspiration
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={() => setDialogOpen(true)}>
              <Plus className="mr-2 size-4" />
              From YouTube or upload
            </DropdownMenuItem>
            <DropdownMenuItem asChild>
              <Link href={`/orgs/${orgSlug}/inspirations/draw`}>
                <Pencil className="mr-2 size-4" />
                Draw inspiration
              </Link>
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </LayoutActions>

      <InspirationDialog open={dialogOpen} onOpenChange={setDialogOpen} />

      <LayoutContent className="flex flex-col gap-4">
        <div className="flex flex-wrap items-center gap-3">
          <div className="relative w-full sm:w-64">
            <Search className="text-muted-foreground absolute top-1/2 left-3 size-4 -translate-y-1/2" />
            <Input
              placeholder="Search inspirations..."
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              className="pl-9"
            />
          </div>
          <Tabs
            value={filter}
            onValueChange={(value) => updateFilter(value as InspirationFilter)}
          >
            <TabsList>
              <TabsTrigger value="mine">My Library</TabsTrigger>
              <TabsTrigger value="all">Community</TabsTrigger>
            </TabsList>
          </Tabs>
          <Select
            value={category ?? "all"}
            onValueChange={(value) =>
              setCategory(
                value === "all" ? undefined : (value as ThumbnailCategory),
              )
            }
          >
            <SelectTrigger className="w-[150px]">
              <SelectValue placeholder="Category" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Categories</SelectItem>
              {THUMBNAIL_CATEGORIES.map((thumbnailCategory) => (
                <SelectItem key={thumbnailCategory} value={thumbnailCategory}>
                  {thumbnailCategory}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {isLoading ? (
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3].map((item) => (
              <Skeleton key={item} className="aspect-video w-full rounded-2xl" />
            ))}
          </div>
        ) : inspirations.length === 0 ? (
          <EmptyState
            title="No inspirations yet"
            description="Add YouTube thumbnails as style references for your generations."
            action={
              <Button onClick={() => setDialogOpen(true)}>
                <Plus className="mr-2 size-4" />
                Add Inspiration
              </Button>
            }
          />
        ) : (
          <>
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {inspirations.map((inspiration) => (
                <InspirationCard
                  key={inspiration.id}
                  inspiration={inspiration}
                  orgSlug={orgSlug}
                />
              ))}
            </div>
            <div ref={loadMoreRef} className="flex justify-center py-8">
              {isFetchingNextPage ? (
                <Loader2 className="text-muted-foreground size-6 animate-spin" />
              ) : hasNextPage ? (
                <Button variant="outline" onClick={() => void fetchNextPage()}>
                  Load more
                </Button>
              ) : null}
            </div>
          </>
        )}
      </LayoutContent>
    </Layout>
  );
}

