success.afterFullFileContent:
import { Button, buttonVariants } from "@/components/ui/button";
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuTrigger,
} from "@/components/ui/context-menu";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { dialogManager } from "@/features/dialog-manager/dialog-manager";
import { deleteInspirationRef } from "@/features/inspiration/inspiration.convex";
import { InspirationDialog } from "@/features/inspiration/inspiration-dialog";
import {
  type InspirationFilter,
  type InspirationListItem,
  isDrawingInspiration,
  useInfiniteInspirations,
} from "@/features/inspiration/inspiration.query";
import {
  Layout,
  LayoutActions,
  LayoutContent,
  LayoutHeader,
  LayoutTitle,
} from "@/features/page/layout";
import { Typography } from "@/components/nowts/typography";
import { EmptyState } from "@/features/organization/loading-state";
import { THUMBNAIL_CATEGORIES, type ThumbnailCategory } from "@/lib/ai/gemini";
import Image from "@/compat/image";
import Link from "@/compat/link";
import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useMutation } from "@/hooks/use-async-mutation";
import { useMutation as useConvexMutation } from "convex/react";
import { formatDistanceToNow } from "date-fns";
import {
  BookOpen,
  EllipsisVertical,
  ExternalLink,
  ImageIcon,
  Loader2,
  MoreVertical,
  Pencil,
  PlayCircle,
  Plus,
  Search,
  Trash2,
} from "lucide-react";
import { useDeferredValue, useEffect, useRef, useState } from "react";
import { toast } from "sonner";

const filterOptions = ["mine", "all"] as const;

type InspirationsSearch = {
  filter?: InspirationFilter;
};

export const Route = createFileRoute("/orgs/$orgSlug/inspirations/")({
  validateSearch: (search: Record<string, unknown>): InspirationsSearch => ({
    filter: filterOptions.includes(search.filter as InspirationFilter)
      ? (search.filter as InspirationFilter)
      : "mine",
  }),
  component: InspirationsRoute,
});

function InspirationsRoute() {
  const { orgSlug } = Route.useParams();
  const navigate = useNavigate({ from: "/orgs/$orgSlug/inspirations/" });
  const routeSearch = Route.useSearch();
  const filter = routeSearch.filter ?? "mine";
  const [category, setCategory] = useState<ThumbnailCategory | undefined>();
  const [search, setSearch] = useState("");
  const deferredSearch = useDeferredValue(search);
  const [dialogOpen, setDialogOpen] = useState(false);
  const loadMoreRef = useRef<HTMLDivElement>(null);
  const { data, isLoading, fetchNextPage, hasNextPage, isFetchingNextPage } =
    useInfiniteInspirations(
      orgSlug,
      filter,
      deferredSearch || undefined,
      category,
    );
  const inspirations = data.pages.flatMap((page) => page.items);

  useEffect(() => {
    const currentRef = loadMoreRef.current;
    if (!currentRef) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting && hasNextPage && !isFetchingNextPage) {
          void fetchNextPage();
        }
      },
      { threshold: 0.1 },
    );

    observer.observe(currentRef);
    return () => observer.unobserve(currentRef);
  }, [hasNextPage, isFetchingNextPage, fetchNextPage]);

  const openTutorialDialog = () => {
    dialogManager.custom({
      title: "How to Use Inspirations",
      description:
        "Learn how to use inspirations to guide your AI thumbnail generation.",
      size: "xl",
      children: (
        <div className="flex flex-col gap-4">
          <div className="aspect-video w-full overflow-hidden rounded-lg">
            <iframe
              src="https://www.tella.tv/video/generez-des-images-ia-avec-inspiration-6i59/embed?b=0&title=0&a=1&loop=0&t=0&muted=0&wt=0"
              title="Inspirations tutorial"
              className="size-full"
              allowFullScreen
              allow="autoplay; fullscreen"
            />
          </div>
          <Link
            href="/docs/guides/inspiration-guide"
            className={buttonVariants({ variant: "outline" })}
          >
            <BookOpen className="mr-2 size-4" />
            Read Full Documentation
          </Link>
        </div>
      ),
    });
  };

  const updateFilter = (nextFilter: InspirationFilter) => {
    void navigate({
      search: (previous) => ({ ...previous, filter: nextFilter }),
    });
  };

  return (
    <Layout size="lg">
      <LayoutHeader>
        <LayoutTitle>Inspirations</LayoutTitle>
      </LayoutHeader>
      <LayoutActions>
        <Button
          variant="outline"
          className="hidden md:inline-flex"
          onClick={openTutorialDialog}
        >
          <PlayCircle className="mr-2 size-4" />
          Watch Tutorial
        </Button>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="icon" className="md:hidden">
              <EllipsisVertical className="size-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={openTutorialDialog}>
              <PlayCircle className="mr-2 size-4" />
              Watch Tutorial
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button>
              <Plus className="mr-2 size-4" />
              Add Inspiration
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={() => setDialogOpen(true)}>
              <Plus className="mr-2 size-4" />
              From YouTube or upload
            </DropdownMenuItem>
            <DropdownMenuItem asChild>
              <Link href={`/orgs/${orgSlug}/inspirations/draw`}>
                <Pencil className="mr-2 size-4" />
                Draw inspiration
              </Link>
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </LayoutActions>

      <InspirationDialog open={dialogOpen} onOpenChange={setDialogOpen} />

      <LayoutContent className="flex flex-col gap-4">
        <div className="flex flex-wrap items-center gap-3">
          <div className="relative w-full sm:w-64">
            <Search className="text-muted-foreground absolute top-1/2 left-3 size-4 -translate-y-1/2" />
            <Input
              placeholder="Search inspirations..."
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              className="pl-9"
            />
          </div>
          <Tabs
            value={filter}
            onValueChange={(value) => updateFilter(value as InspirationFilter)}
          >
            <TabsList>
              <TabsTrigger value="mine">My Library</TabsTrigger>
              <TabsTrigger value="all">Community</TabsTrigger>
            </TabsList>
          </Tabs>
          <Select
            value={category ?? "all"}
            onValueChange={(value) =>
              setCategory(
                value === "all" ? undefined : (value as ThumbnailCategory),
              )
            }
          >
            <SelectTrigger className="w-[150px]">
              <SelectValue placeholder="Category" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Categories</SelectItem>
              {THUMBNAIL_CATEGORIES.map((thumbnailCategory) => (
                <SelectItem key={thumbnailCategory} value={thumbnailCategory}>
                  {thumbnailCategory}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {isLoading ? (
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3].map((item) => (
              <Skeleton key={item} className="aspect-video w-full rounded-2xl" />
            ))}
          </div>
        ) : inspirations.length === 0 ? (
          <EmptyState
            title="No inspirations yet"
            description="Add YouTube thumbnails as style references for your generations."
            action={
              <Button onClick={() => setDialogOpen(true)}>
                <Plus className="mr-2 size-4" />
                Add Inspiration
              </Button>
            }
          />
        ) : (
          <>
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {inspirations.map((inspiration) => (
                <InspirationCard
                  key={inspiration.id}
                  inspiration={inspiration}
                  orgSlug={orgSlug}
                />
              ))}
            </div>
            <div ref={loadMoreRef} className="flex justify-center py-8">
              {isFetchingNextPage ? (
                <Loader2 className="text-muted-foreground size-6 animate-spin" />
              ) : hasNextPage ? (
                <Button variant="outline" onClick={() => void fetchNextPage()}>
                  Load more
                </Button>
              ) : null}
            </div>
          </>
        )}
      </LayoutContent>
    </Layout>
  );
}

function InspirationCard({
  inspiration,
  orgSlug,
}: {
  inspiration: InspirationListItem;
  orgSlug: string;
}) {
  const deleteInspiration = useConvexMutation(deleteInspirationRef);
  const detailsHref = `/orgs/${orgSlug}/inspirations/${inspiration.id}`;
  const hasImage = Boolean(inspiration.thumbnailUrls[0]);
  const relativeDate = formatDistanceToNow(new Date(inspiration.createdAt));

  const deleteMutation = useMutation({
    mutationFn: async () => {
      return deleteInspiration({ orgSlug, inspirationId: inspiration.id });
    },
    onSuccess: async () => {
      toast.success("Inspiration deleted");
    },
    onError: (error) => {
      toast.error(error.message);
    },
  });

  const handleDelete = () => {
    dialogManager.confirm({
      title: "Delete inspiration",
      description:
        "Are you sure you want to delete this inspiration? This action cannot be undone.",
      variant: "destructive",
      action: {
        label: "Delete",
        variant: "destructive",
        onClick: async () => {
          await deleteMutation.mutateAsync();
        },
      },
    });
  };

  return (
    <ContextMenu>
      <ContextMenuTrigger asChild>
        <div className="group relative aspect-video cursor-pointer overflow-hidden rounded-2xl border border-border transition-colors duration-150 hover:border-primary/50">
          {/* Full-bleed image */}
          <Link href={detailsHref} className="absolute inset-0 block">
            {hasImage ? (
              <Image
                src={inspiration.thumbnailUrls[0]}
                alt={inspiration.name}
                fill
                className="object-cover"
              />
            ) : (
              <div className="bg-muted flex size-full items-center justify-center">
                <ImageIcon className="text-muted-foreground size-10" />
              </div>
            )}
          </Link>

          {/* Gradient scrim — only over bottom half for text legibility */}
          {hasImage ? (
            <div
              className="pointer-events-none absolute inset-0"
              style={{
                background:
                  "linear-gradient(to top, oklch(0.10 0 0 / 0.82) 0%, transparent 50%)",
              }}
            />
          ) : null}

          {/* Three-dot menu — near-invisible at rest, revealed on hover */}
          <div className="absolute top-2 right-2 z-20 opacity-35 transition-opacity duration-150 group-hover:opacity-100">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  className="size-7 rounded-md hover:bg-black/50"
                  onClick={(event) => {
                    event.preventDefault();
                    event.stopPropagation();
                  }}
                >
                  <MoreVertical className="size-3.5 text-white" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuItem asChild>
                  <Link href={detailsHref}>
                    <ExternalLink className="mr-2 size-4" />
                    View Details
                  </Link>
                </DropdownMenuItem>
                {isDrawingInspiration(inspiration) ? (
                  <DropdownMenuItem asChild>
                    <Link
                      href={`/orgs/${orgSlug}/inspirations/draw?inspirationId=${inspiration.id}`}
                    >
                      <Pencil className="mr-2 size-4" />
                      Edit drawing
                    </Link>
                  </DropdownMenuItem>
                ) : null}
                {inspiration.youtubeUrl ? (
                  <DropdownMenuItem asChild>
                    <a
                      href={inspiration.youtubeUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      <ExternalLink className="mr-2 size-4" />
                      Open YouTube
                    </a>
                  </DropdownMenuItem>
                ) : null}
                <DropdownMenuItem
                  onClick={handleDelete}
                  className="text-destructive focus:text-destructive"
                >
                  <Trash2 className="mr-2 size-4" />
                  Delete
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>

          {/* Bottom info — title and relative date, subtle overlay */}
          {hasImage ? (
            <Link
              href={detailsHref}
              className="absolute inset-x-0 bottom-0 z-10 block p-3"
            >
              <Typography
                variant="small"
                as="h3"
                className="line-clamp-1 text-white/75"
              >
                {inspiration.name}
              </Typography>
              <Typography
                variant="muted"
                as="p"
                className="mt-0.5 text-[10.5px] text-white/30"
              >
                {relativeDate} ago
              </Typography>
            </Link>
          ) : null}
        </div>
      </ContextMenuTrigger>

      <ContextMenuContent>
        <ContextMenuItem asChild>
          <Link href={detailsHref}>
            <ExternalLink className="mr-2 size-4" />
            View Details
          </Link>
        </ContextMenuItem>
        {isDrawingInspiration(inspiration) ? (
          <ContextMenuItem asChild>
            <Link
              href={`/orgs/${orgSlug}/inspirations/draw?inspirationId=${inspiration.id}`}
            >
              <Pencil className="mr-2 size-4" />
              Edit drawing
            </Link>
          </ContextMenuItem>
        ) : null}
        {inspiration.youtubeUrl ? (
          <ContextMenuItem asChild>
            <a
              href={inspiration.youtubeUrl}
              target="_blank"
              rel="noopener noreferrer"
            >
              <ExternalLink className="mr-2 size-4" />
              Open YouTube
            </a>
          </ContextMenuItem>
        ) : null}
        <ContextMenuItem
          onClick={handleDelete}
          className="text-destructive focus:text-destructive"
        >
          <Trash2 className="mr-2 size-4" />
          Delete
        </ContextMenuItem>
      </ContextMenuContent>
    </ContextMenu>
  );
}

success.beforeFullFileContent:
import { TitleUpdateForm } from "@/components/nowts/title-update-form";
import { Badge } from "@/components/ui/badge";
import { Button, buttonVariants } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  InspirationDetailDialog,
  InspirationSourceVideoCard,
} from "@/features/inspiration/inspiration-detail-dialog";
import type { InspirationListItem } from "@/features/inspiration/inspiration.query";
import { useInspiration } from "@/features/inspiration/inspiration.query";
import {
  Layout,
  LayoutActions,
  LayoutContent,
  LayoutHeader,
} from "@/features/page/layout";
import { useCurrentOrg } from "@/features/organization/current-org-store";
import { LoadingState } from "@/features/organization/loading-state";
import Image from "@/compat/image";
import Link from "@/compat/link";
import { formatDate } from "@/lib/format/date";
import { formatScopedTitle } from "@/lib/metadata";
import { usePageMetadata } from "@/lib/use-page-metadata";
import { createFileRoute } from "@tanstack/react-router";
import { useMutation as useConvexMutation } from "convex/react";
import { makeFunctionReference } from "convex/server";
import {
  Calendar,
  ExternalLink,
  ImageIcon,
  Pencil,
  User,
  UserX,
} from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

const updateInspirationNameRef = makeFunctionReference<
  "mutation",
  { orgSlug: string; inspirationId: string; name: string },
  { id: string; name: string }
>("inspiration:updateName");

export const Route = createFileRoute(
  "/orgs/$orgSlug/inspirations/$inspirationId",
)({
  component: InspirationDetailRoute,
});

function InspirationDetailRoute() {
  const { orgSlug, inspirationId } = Route.useParams();
  const currentOrg = useCurrentOrg();
  const { data: inspiration, isLoading } = useInspiration(
    orgSlug,
    inspirationId,
  );
  const updateInspirationName = useConvexMutation(updateInspirationNameRef);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [localInspiration, setLocalInspiration] =
    useState<InspirationListItem | null>(null);
  const activeInspiration =
    localInspiration?.id === inspirationId ? localInspiration : inspiration;
  const firstThumbnail = activeInspiration?.thumbnailUrls[0];

  usePageMetadata(
    activeInspiration
      ? {
          title: formatScopedTitle([
            activeInspiration.name,
            currentOrg?.name ?? orgSlug,
          ]),
          description: activeInspiration.aiDescription,
          image: firstThumbnail,
          path: `/orgs/${orgSlug}/inspirations/${inspirationId}`,
          noIndex: true,
        }
      : null,
  );

  if (isLoading || !activeInspiration) {
    return <LoadingState label="Loading inspiration" />;
  }

  const saveTitle = async (name: string) => {
    try {
      await updateInspirationName({ orgSlug, inspirationId, name });
      setLocalInspiration({ ...activeInspiration, name });
      toast.success("Inspiration renamed");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Failed to rename");
    }
  };

  return (
    <Layout size="lg">
      <LayoutHeader>
        <TitleUpdateForm
          key={`${orgSlug}:${inspirationId}:${activeInspiration.name}`}
          title={activeInspiration.name}
          onUpdate={saveTitle}
        />
      </LayoutHeader>
      <LayoutActions>
        <Link
          href={`/orgs/${orgSlug}/thumbnails/new?inspiration=${activeInspiration.id}`}
          className={buttonVariants()}
        >
          Use this inspiration
        </Link>
        <Button variant="outline" onClick={() => setDialogOpen(true)}>
          <Pencil className="mr-2 size-4" />
          Edit Reference
        </Button>
      </LayoutActions>

      <LayoutContent className="flex flex-col gap-6">
        <div className="flex flex-wrap items-center gap-2 border-b pb-4">
          {activeInspiration.category ? (
            <Badge variant="secondary">{activeInspiration.category}</Badge>
          ) : null}
          <Badge variant="outline" className="gap-1">
            <Calendar size={12} />
            {formatDate(new Date(activeInspiration.createdAt))}
          </Badge>
          <Badge
            variant={activeInspiration.hasPlaceholder ? "secondary" : "outline"}
            className="gap-1"
          >
            {activeInspiration.hasPlaceholder ? (
              <UserX size={12} />
            ) : (
              <User size={12} />
            )}
            {activeInspiration.hasPlaceholder ? "Anonymized" : "Original"}
          </Badge>
          {activeInspiration.youtubeUrl ? (
            <Link
              href={activeInspiration.youtubeUrl}
              target="_blank"
              rel="noopener noreferrer"
            >
              <Badge variant="outline" className="gap-1" asChild>
                <span>
                  <ExternalLink size={12} />
                  YouTube Source
                </span>
              </Badge>
            </Link>
          ) : null}
        </div>

        {firstThumbnail ? (
          <div className="relative aspect-video w-full overflow-hidden rounded-lg border">
            <Image
              src={firstThumbnail}
              alt={activeInspiration.name}
              fill
              className="object-cover"
              priority
            />
          </div>
        ) : (
          <div className="bg-muted flex aspect-video w-full items-center justify-center rounded-lg border">
            <ImageIcon className="text-muted-foreground size-12" />
          </div>
        )}

        <InspirationSourceVideoCard inspiration={activeInspiration} />

        {activeInspiration.aiDescription ? (
          <header className="flex flex-col gap-2 border-b pb-6">
            <h2 className="text-sm font-medium">AI Description</h2>
            <p className="text-muted-foreground whitespace-pre-wrap">
              {activeInspiration.aiDescription}
            </p>
          </header>
        ) : null}

        {activeInspiration.thumbnailUrls.length > 1 ? (
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4">
            {activeInspiration.thumbnailUrls.slice(1).map((url, index) => (
              <div
                key={`${url}-${index}`}
                className="bg-muted relative aspect-video overflow-hidden rounded-lg border"
              >
                <Image
                  src={url}
                  alt={`Thumbnail ${index + 2}`}
                  fill
                  className="object-cover"
                />
              </div>
            ))}
          </div>
        ) : null}

        <Card>
          <CardHeader>
            <CardTitle>Your Thumbnails</CardTitle>
            <CardDescription>
              Thumbnails you created using this inspiration
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex flex-col items-center justify-center py-8 text-center">
              <p className="text-muted-foreground text-sm">
                Create a thumbnail with this inspiration to see it here.
              </p>
              <Link
                href={`/orgs/${orgSlug}/thumbnails/new?inspiration=${activeInspiration.id}`}
                className={buttonVariants({
                  variant: "secondary",
                  size: "sm",
                  className: "mt-4",
                })}
              >
                Create your first
              </Link>
            </div>
          </CardContent>
        </Card>
      </LayoutContent>

      <InspirationDetailDialog
        inspiration={activeInspiration}
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        currentOrgId={currentOrg?.id ?? ""}
        orgSlug={orgSlug}
        onImagesUpdated={(thumbnailUrls) => {
          setLocalInspiration({ ...activeInspiration, thumbnailUrls });
        }}
        onInspirationCopied={(newInspiration) => {
          setLocalInspiration(newInspiration);
        }}
        onInspirationAnonymized={(updatedInspiration) => {
          setLocalInspiration(updatedInspiration);
        }}
      />
    </Layout>
  );
}

