import { SiteConfig } from "@/site-config";

export type Metadata = {
  [key: string]: unknown;
  title?: string | { default?: string; template?: string };
  description?: string;
  keywords?: string[] | string;
  alternates?: {
    canonical?: string;
  };
  openGraph?: {
    title?: string;
    description?: string;
    url?: string;
    type?: string;
    images?:
      | string
      | string[]
      | {
          url?: string;
        }
