    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Failed to save drawing";
      setSaveError(message);
      toast.error(message);
    } finally {
      setIsSaving(false);
    }
  };

  const handleInsertImage = () => {
    fileInputRef.current?.click();
  };

