    sourceVideoTitle: inspiration.sourceVideoTitle ?? null,
    sourceVideoAuthor: inspiration.sourceVideoAuthor ?? null,
    sourceVideoThumbnailUrl: inspiration.sourceVideoThumbnailUrl ?? null,
  };
}

