    }

    if (drag.kind === "pencil") {
      setDocument({
        ...documentRef.current,
        elements: documentRef.current.elements.map((element) => {
          if (element.id !== drag.id || element.type !== "pencil") return element;
          return {
            ...element,
            points: [
              ...element.points,
              { x: point.x - element.x, y: point.y - element.y },
