            };
            return;
          }
        }
      }

      const hit = hitTestTopElement(documentRef.current.elements, point);
      if (hit) {
        const nextSelected = event.shiftKey
          ? selected.includes(hit.id)
            ? selected.filter((id) => id !== hit.id)
            : [...selected, hit.id]
          : selected.includes(hit.id)
            ? selected
            : [hit.id];
        setSelectedIds(nextSelected);
        setEditingTextId(null);
        dragRef.current = {
          kind: "move",
          start: point,
          origin: documentRef.current.elements.map((element) =>
            structuredClone(element),
          ),
        };
        return;
      }

      setSelectedIds([]);
      setEditingTextId(null);
      return;
    }

    if (currentTool === "text") {
      const element = createTextElement({
        x: point.x,
        y: point.y,
        width: 420,
        height: 90,
        text: "",
      });
      commit({
        ...documentRef.current,
        elements: [...documentRef.current.elements, element],
      });
      setSelectedIds([element.id]);
      setEditingTextId(element.id);
      setTool("select");
      return;
    }

    if (currentTool === "person") {
      const element = createPersonElement({
        x: point.x - 90,
        y: point.y - 180,
        width: 180,
        height: 360,
      });
      commit({
        ...documentRef.current,
        elements: [...documentRef.current.elements, element],
      });
      setSelectedIds([element.id]);
      setTool("select");
      return;
    }

    if (currentTool === "pencil") {
      const element = createPencilElement({
        x: point.x,
        y: point.y,
        points: [{ x: 0, y: 0 }],
      });
      setDocument({
