        return;
      }
      if (meta && event.key.toLowerCase() === "c") {
        if (isTextTarget(event.target)) return;
        event.preventDefault();
        copySelected();
        return;
      }
      if (meta && event.key.toLowerCase() === "v") {
        if (isTextTarget(event.target)) return;
        event.preventDefault();
        pasteClipboard();
        return;
      }
      if (meta && event.key.toLowerCase() === "d") {
        event.preventDefault();
        duplicateSelected();
        return;
      }
      if (event.key === "Delete" || event.key === "Backspace") {
        if (isTextTarget(event.target) || editingTextIdRef.current) return;
        event.preventDefault();
        deleteSelected();
        return;
      }

      if (isTextTarget(event.target) || editingTextIdRef.current || meta) return;
      const toolByKey: Record<string, DrawingTool> = {
        v: "select",
        t: "text",
        a: "arrow",
        r: "rect",
        o: "ellipse",
        p: "pencil",
      };
      const nextTool = toolByKey[event.key.toLowerCase()];
      if (nextTool) {
