    hdr_txt = "\n".join(f"{k}: {v}" for k,v in r["headers"].items())
    (PAGES / f"{name}.headers").write_text(f"HTTP {r['status']}\n{hdr_txt}\nerror={r['error']}\n")
    # save small bodies fully; truncate huge html
    body = r["body"]
    if len(body) > 200_000:
        (PAGES / f"{name}.body").write_bytes(body[:2000] + b"\n...truncated...\n")
        (PAGES / f"{name}.size").write_text(str(len(body)))
    else:
        (PAGES / f"{name}.body").write_bytes(body)
    loc = r["headers"].get("Location") or r["headers"].get("location")
    ctype = r["headers"].get("Content-Type") or r["headers"].get("content-type","")
    matched = r["headers"].get("x-matched-path") or r["headers"].get("X-Matched-Path","")
    cookies = r["headers"].get("Set-Cookie") or r["headers"].get("set-cookie","")
    snippet = body[:80].decode("utf-8","replace").replace("\n"," ")
    row = {
        "path": p, "status": r["status"], "bytes": len(body), "ctype": ctype,
        "matched": matched, "location": loc, "set_cookie": cookies[:200],
        "error": r["error"], "snippet": snippet[:120],
    }
    results.append(row)
    print(f"{r['status']:3} {len(body):7} {p:45} matched={matched} loc={loc} cookie={bool(cookies)} {snippet[:60]}")

(HTTP / "probe-results.json").write_text(json.dumps(results, indent=2))
