import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";

type InspirationMultiSelectorProps = {
  value: string[];
  onChange: (inspirationIds: string[]) => void;
