    if (!copy) throw new Error("Inspiration not found");
    return toInspirationRow(copy);
  },
});

const MAX_DRAWING_DATA_LENGTH = 500_000;

function assertDrawingData(drawingData: string) {
  if (!drawingData.trim()) throw new Error("Drawing data is required");
  if (drawingData.length > MAX_DRAWING_DATA_LENGTH) {
    throw new Error("Drawing is too large to save");
  }
}

