export const DRAWING_VERSION = 1;
export const CANVAS_WIDTH = 1280;
export const CANVAS_HEIGHT = 720;

export const DRAWING_TOOLS = [
  "select",
  "text",
  "arrow",
  "rect",
  "ellipse",
  "pencil",
  "image",
  "person",
] as const;

export type DrawingTool = (typeof DRAWING_TOOLS)[number];

export const HANDLE_IDS = [
  "nw",
  "n",
  "ne",
  "e",
  "se",
  "s",
  "sw",
  "w",
