function clientToCanvas(
  event: Pick<PointerEvent, "clientX" | "clientY">,
  svg: SVGSVGElement,
): Point {
  const rect = svg.getBoundingClientRect();
  return {
    x: ((event.clientX - rect.left) / rect.width) * CANVAS_WIDTH,
    y: ((event.clientY - rect.top) / rect.height) * CANVAS_HEIGHT,
  };
}

