  const transform = element.rotation
    ? `rotate(${element.rotation} ${element.x + element.width / 2} ${element.y + element.height / 2})`
    : undefined;

  return (
    <g>
      <rect
        x={bounds.x}
        y={bounds.y}
        width={bounds.width}
        height={bounds.height}
        fill="none"
        stroke="#2563eb"
        strokeWidth={1.5}
        strokeDasharray="6 4"
        transform={transform}
      />
      <line
        x1={handles.n.x}
        y1={handles.n.y}
        x2={handles.rotate.x}
        y2={handles.rotate.y}
        stroke="#2563eb"
        strokeWidth={1}
      />
      {Object.entries(handles).map(([id, point]) => (
        <rect
          key={id}
          x={point.x - 5}
          y={point.y - 5}
          width={10}
          height={10}
          rx={id === "rotate" ? 5 : 1.5}
          fill={id === "rotate" ? "#2563eb" : "#fff"}
          stroke="#2563eb"
          strokeWidth={1.5}
        />
      ))}
    </g>
  );
}

