    if (drag.kind === "create") {
      setTool("select");
    }
  }, [commit]);

  const doubleClick = useCallback((point: Point) => {
    const hit = hitTestTopElement(documentRef.current.elements, point);
    if (hit?.type === "text") {
      setSelectedIds([hit.id]);
      setEditingTextId(hit.id);
