    if (editingTextIdRef.current) {
      stopTextEditing();
      return "text";
    }
    if (selectedIdsRef.current.length > 0) {
      clearSelection();
      return "selection";
    }
    if (toolRef.current !== "select") {
      setTool("select");
      return "tool";
    }
    return "none";
  }, [clearSelection, stopTextEditing]);

