        x: point.x,
        y: point.y,
        width: 420,
        height: 90,
        text: "",
      });
      commit({
        ...documentRef.current,
        elements: [...documentRef.current.elements, element],
      });
      setSelectedIds([element.id]);
      setEditingTextId(element.id);
      setTool("select");
      return;
    }

    if (currentTool === "person") {
      const element = createPersonElement({
        x: point.x - 90,
        y: point.y - 180,
        width: 180,
        height: 360,
      });
      commit({
        ...documentRef.current,
        elements: [...documentRef.current.elements, element],
      });
      setSelectedIds([element.id]);
      setTool("select");
      return;
    }

    if (currentTool === "pencil") {
      const element = createPencilElement({
        x: point.x,
        y: point.y,
        points: [{ x: 0, y: 0 }],
      });
      setDocument({
        ...documentRef.current,
        elements: [...documentRef.current.elements, element],
      });
      dragRef.current = { kind: "pencil", id: element.id };
      return;
    }

    const created =
      currentTool === "rect"
        ? createRectElement({ x: point.x, y: point.y, width: MIN_CREATE, height: MIN_CREATE })
        : currentTool === "ellipse"
          ? createEllipseElement({
              x: point.x,
              y: point.y,
              width: MIN_CREATE,
              height: MIN_CREATE,
            })
          : createArrowElement({ x: point.x, y: point.y, width: 1, height: 1 });

    setDocument({
      ...documentRef.current,
      elements: [...documentRef.current.elements, created],
    });
