        x: point.x - drag.start.x,
        y: point.y - drag.start.y,
      };
      setDocument({
        ...documentRef.current,
        elements: moveElements(
          drag.origin,
          new Set(selectedIdsRef.current),
          delta,
        ),
      });
      return;
