    duplicateSelected,
    handleEscape,
    pasteClipboard,
    redo,
    undo,
  ]);

  useEffect(() => {
    const onBeforeUnload = (event: BeforeUnloadEvent) => {
      if (!isDirty) return;
      event.preventDefault();
      event.returnValue = "";
    };
    window.addEventListener("beforeunload", onBeforeUnload);
    return () => window.removeEventListener("beforeunload", onBeforeUnload);
  }, [isDirty]);

  return {
    document,
    selectedIds,
    selectedElements,
    tool,
    setTool,
    editingTextId,
    isDirty,
    shiftKey,
    pointerDown,
    pointerMove,
    pointerUp,
    doubleClick,
    handleEscape,
    stopTextEditing,
    updateText,
    applyTemplate,
    insertImage,
    insertPerson,
    updateSelectedStyle,
    duplicateSelected,
    deleteSelected,
    undo,
    redo,
    loadDocument,
    markSaved,
    parseDrawingDocument,
  };
}

