    window.addEventListener("keyup", onKeyUp);
    return () => {
      window.removeEventListener("keydown", onKeyDown, true);
      window.removeEventListener("keyup", onKeyUp);
    };
  }, [
    copySelected,
    deleteSelected,
    duplicateSelected,
    handleEscape,
    pasteClipboard,
    redo,
    undo,
  ]);

