    document,
    selectedIds,
    selectedElements,
    tool,
    setTool,
    editingTextId,
    isDirty,
    shiftKey,
    pointerDown,
    pointerMove,
    pointerUp,
    doubleClick,
    handleEscape,
    stopTextEditing,
    updateText,
    applyTemplate,
    insertImage,
    insertPerson,
    updateSelectedStyle,
    duplicateSelected,
    deleteSelected,
    undo,
    redo,
    loadDocument,
    markSaved,
    parseDrawingDocument,
  };
}

